def with_notebooks(root: Path) -> list[str]:
    names = [p.name for p in recipe_dirs(root) if (p / NOTEBOOK).is_file()]
    for name in names:
        if not RECIPE_NAME.fullmatch(name):
            raise SystemExit(
                f"recipe folder name {name!r} is not NN-slug (01–99), 100-slug or _template"
            )
    return names

def select(root: Path, base: str | None, head: str | None, dots: str = "...") -> list[str]:
    """The recipe folders to execute (see the module docstring)."""
    everything = with_notebooks(root)
    if base is None or head is None:
        return everything
    chosen: set[str] = set()
    for path in changed_paths(root, base, head, dots):
        if path == "README.md":
            continue
        parts = path.split("/")
        if len(parts) >= 3 and parts[0] == "recipes":
            chosen.add(parts[1])
        else:
            return everything
    return [name for name in everything if name in chosen]

def test_recipe_pull_request_with_the_generated_readme_still_selects_only_its_recipe(tree):
    def change(root):
        write(root, "recipes/02-second/notebook.ipynb", NB.replace("5}", "5} "))
        write(root, "README.md", "readme, regenerated\n")

    assert selected(tree, change) == ["02-second"]

notebooks:
  name: Notebooks (execute)
  needs: [discover, execute]
  if: always()
  runs-on: ubuntu-latest
  timeout-minutes: 5
  steps:
    # The one stable name for branch protection: green only when discovery succeeded and every
    # selected notebook passed (or none was selected, which a README-only change does).
    - name: Summarise
      env:
        DISCOVER: ${{ needs.discover.result }}
        EXECUTE: ${{ needs.execute.result }}
        COUNT: ${{ needs.discover.outputs.count }}
      run: |
        echo "discover=$DISCOVER execute=$EXECUTE notebooks=$COUNT"
        [ "$DISCOVER" = "success" ] || { echo "discovery did not succeed"; exit 1; }
        if [ "$COUNT" = "0" ]; then
          [ "$EXECUTE" = "skipped" ] || { echo "no notebook selected but execute ran"; exit 1; }
        else
          [ "$EXECUTE" = "success" ] || { echo "a notebook job did not succeed"; exit 1; }
        fi
